'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 mountain:'<path d="m3 19 7-12 4 7 3-5 4 10H3Z"/><path d="m8 10 2 3 2-3"/>',
 people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',
 buddy:'<circle cx="7" cy="8" r="3"/><circle cx="17" cy="8" r="3"/><path d="M2 21v-3a5 5 0 0 1 10 0v3m0-3a5 5 0 0 1 10 0v3"/>',
 compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6 6-2Z"/>',
 mind:'<path d="M9 19H6a3 3 0 0 1-3-3v-4a4 4 0 0 1 3-4 4 4 0 0 1 6-4 4 4 0 0 1 6 4 4 4 0 0 1 3 4v4a3 3 0 0 1-3 3h-3M12 4v17M7 12h5m5 3h-5"/>',
 balance:'<circle cx="12" cy="12" r="8"/><path d="M12 4c-6 2 6 6 0 8s6 6 0 8"/><circle cx="12" cy="8" r=".7"/><circle cx="12" cy="16" r=".7"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 leaf:'<path d="M20 4C4 2 2 14 7 18S22 15 20 4ZM5 21l10-11"/>',
 coffee:'<path d="M4 8h12v8a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5V8Zm12 1h2a3 3 0 0 1 0 6h-2M7 2v3m4-3v3"/>',
 body:'<path d="M5 7v10M2 9v6m17-8v10m3-8v6M5 12h14"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.compass}</svg>`;
const categories=['Hiking','Deporte','Camping','Café y charla','Bienestar','Voluntariado'];
const labels={'Deporte':'Sport','Café y charla':'Coffee & conversation','Bienestar':'Wellbeing','Voluntariado':'Volunteering','Tranquilo':'Easygoing','Intermedio':'Moderate','Activo':'Active','Presencial':'In person','Ambos':'Online & in person'};
const label=v=>labels[v]||v;
const pillarData=[
 {name:'Body',icon:'body',text:'Build your strength. Move with intention and create habits that last.',practice:'Make room for movement',description:'Choose an activity you enjoy and a realistic time this week. A repeatable first step matters more than a perfect plan.',steps:['Choose a walk, a workout or an activity you enjoy.','Make time for it in your week.','Choose an intensity that feels right for you.','Invite someone to share the experience.']},
 {name:'Mind',icon:'mind',text:'Create space for clarity. Reflection, curiosity and a little room to think.',practice:'Five minutes for yourself',description:'Pause and notice your day without judging it. You do not need perfect words; honest ones are enough.',steps:['Notice what gave you energy today.','Notice what took it away.','Choose one small thing you would like to do differently tomorrow.']},
 {name:'Balance',icon:'balance',text:'Find your centre. More presence, more rest, more of your own rhythm.',practice:'A pause with intention',description:'Progress is not always about speed. Take a moment away from screens to notice how you feel.',steps:['Find a comfortable, quiet place.','Breathe naturally.','Notice whether you need rest, movement or company.','Choose a small action that meets that need.']},
 {name:'Purpose',icon:'compass',text:'Choose your direction. Meaningful goals, brought closer one step at a time.',practice:'Turn intention into a next step',description:'A clear direction can begin with a simple question: what deserves more of my attention?',steps:['Choose an area of life you want to care for.','Write down why it matters.','Identify a practical step for this week.','Talk it through with someone you trust.']}
];
const state={user:null,profile:null,admin:false,routeVersion:0,filters:{q:'',city:'',category:''},dialogContext:null,toastTimer:null,device:'',period:30};
const db=window.supabase?.createClient(window.TREKSOR_CONFIG.url,window.TREKSOR_CONFIG.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'treksor-web-auth'}});
const main=$('#main');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000)}
function errorText(e){const m=String(e?.message||'');if(e?.code==='23505')return 'This already exists. Check My space to continue.';if(e?.code==='42501')return 'This action is not available for your account. Please check your session.';if(m.includes('Invalid login'))return 'The email or password is incorrect.';if(m.includes('Email not confirmed'))return 'Confirm your email before signing in.';if(/rate limit/i.test(m))return 'Too many attempts. Please wait a few minutes.';if(/password/i.test(m))return 'Please use a password with at least 8 characters.';if(e?.userMessage)return e.userMessage;return 'We could not complete this action. Check your connection and try again.'}
function fail(message){throw {userMessage:message}}
async function query(request){const {data,error}=await request;if(error)throw error;return data}
function route(){let p=(location.hash.replace(/^#/,'')||'/').split('?')[0];return p.replace('/ecosistema','/ecosystem').replace('/espacio','/space').replace('/uno-a-uno','/one-to-one').replace('/mentores','/mentors').replace('/grupo/','/group/').replace('/conexion/','/connection/').replace('/gestion','/admin')}
function go(p){if(route()===p)render();else location.hash=p}
function initials(n){return String(n||'T').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function avatar(n,large=false,url=''){const valid=/^https:\/\//.test(url);return `<span class="avatar${large?' large':''}">${valid?`<img src="${esc(url)}" alt="${esc(n)}" referrerpolicy="no-referrer">`:esc(initials(n))}</span>`}
function date(v){const d=new Date(v);return Number.isNaN(d.getTime())?'Not available':new Intl.DateTimeFormat('en-AU',{dateStyle:'medium',timeStyle:'short'}).format(d)}
function btn(text,action,id='',extra=''){return `<button class="button small ${extra}" data-action="${action}"${id?` data-id="${esc(id)}"`:''}>${text}</button>`}
function empty(title,description,action='',symbol='compass'){return `<div class="empty"><div class="empty-visual">${icon(symbol)}</div><div><h3>${title}</h3><p>${description}</p>${action}</div></div>`}
function pageTop(eyebrow,title,description,action=''){return `<section class="page-top"><div class="wrap"><div class="eyebrow">${eyebrow}</div><div class="page-top-row"><div><h1>${title}</h1><p>${description}</p></div>${action}</div></div></section>`}
function openDialog(title,content,eyebrow='TREKSOR'){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class="eyebrow">${eyebrow}</div><h2 id="dialog-title">${title}</h2>${content}`;if(!d.open)d.showModal()}
function closeDialog(){$('#dialog').close();state.dialogContext=null}
function needUser(){if(state.user)return true;authDialog();return false}
function needProfile(){if(!needUser())return false;if(!state.profile){profileDialog();return false}return true}
function updateNav(){const p=route();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='home'?p==='/':p.includes(a.dataset.nav)));$('#account-nav').innerHTML=state.user?'<a class="button small ghost" href="#/space">My space ↗</a>':btn('Sign in ↗','login','','ghost')}
async function loadProfile(){const id=state.user?.id;if(!id){state.profile=null;state.admin=false;return}const [p,a]=await Promise.all([query(db.from('web_profiles').select('*').eq('user_id',id).maybeSingle()),query(db.from('admin_members').select('user_id').eq('user_id',id).maybeSingle())]);if(state.user?.id===id){state.profile=p;state.admin=!!a}}
function renderHome(){return `<section class="hero"><img class="hero-photo" src="/assets/forest.jpg" alt="Hikers on a mountain trail overlooking the forest" fetchpriority="high"><span class="vertical-note">YOUR NEXT CHAPTER STARTS HERE</span><div class="wrap"><div class="hero-copy"><div class="eyebrow">A LIFE WITH MORE INTENTION</div><h1>Your journey.<br>Your people.<br><em>Your own way.</em></h1><p>Build strength. Find clarity. Connect with people who want to move forward, too.</p><div class="hero-actions"><a class="button" href="#/community">Find your community ↗</a><a class="text-link" href="#/progress">See your progress →</a></div></div></div><div class="hero-foot"><span>BODY &nbsp; / &nbsp; MIND &nbsp; / &nbsp; BALANCE &nbsp; / &nbsp; PURPOSE</span><span>A LITTLE FURTHER. A LITTLE CLOSER TO YOU.</span></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">FOUR PILLARS. ONE JOURNEY.</div><h2>Room to grow.<br>In every direction.</h2></div><p>Your wellbeing is connected. Discover movement, reflection, balance and purpose in one place.</p></div><div class="pillars">${pillarData.map((p,i)=>`<article class="pillar"><div class="pillar-number">0${i+1}</div><span class="pillar-icon">${icon(p.icon)}</span><h3>${p.name}</h3><p>${p.text}</p><a class="text-link" href="#/ecosystem">Explore ↗</a></article>`).join('')}</div></div></section>
<section class="section muted-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">COMMUNITY</div><h2>Better together.<br>At your own pace.</h2></div><p>There is more than one way to belong. Find a group, start with one person or connect with a mentor.</p></div><div class="paths">${[{icon:'people',number:'01 / EXPLORE',title:'A shared plan. Your people.',text:'Hiking, sport, camping or a good conversation. Find people with a common interest and a reason to get out there.',link:'/community',cta:'Explore groups'},{icon:'buddy',number:'02 / CONNECT',title:'Two is a great start.',text:'Big groups are not for everyone. Meet one person, share a simple activity and let trust grow in its own time.',link:'/community/one-to-one',cta:'Find a companion'},{icon:'compass',number:'03 / GROW',title:'A little perspective.',text:'Talk to a mentor about your goals, the questions on your mind and the next step you want to take.',link:'/community/mentors',cta:'Explore mentors'}].map(p=>`<article class="path"><span class="path-icon">${icon(p.icon)}</span><span class="number">${p.number}</span><h3>${p.title}</h3><p>${p.text}</p><a class="text-link" href="#${p.link}">${p.cta} ↗</a></article>`).join('')}</div><div class="info-strip">${icon('shield')}<span>You choose who to connect with. Private conversations start only when an invitation is accepted.</span></div></div></section>
<section class="section"><div class="wrap"><div class="mentor-banner"><div class="mentor-art" aria-hidden="true"><div class="orbits"><i class="orbit-dot"></i><i class="orbit-dot second"></i><span>↗</span></div></div><div class="mentor-copy"><div class="eyebrow">ONE ACCOUNT. YOUR WHOLE JOURNEY.</div><h2>Your progress.<br>Beyond your phone.</h2><p>Your Treksor profile connects the app and the web. See your training, habits and progress together, then find people to share the next step with.</p><a class="button ghost" href="#/progress">Open my progress ↗</a></div></div><div class="quote-band"><p>You do not need to become someone else.<br>Start by becoming more yourself.</p><span>THE TREKSOR SPIRIT</span></div><div class="faq"><div class="eyebrow">BEFORE YOU BEGIN</div><h2>A little more clarity.</h2><details><summary>Can I use my app account?</summary><p>Yes. Use the same email and password as in the Treksor app. Your name and profile photo are shared across both. Open the updated app while connected to sync your progress.</p></details><details><summary>What if big groups feel overwhelming?</summary><p>One-to-one is a space to start smaller. Choose your interests and pace, send an invitation and decide together whether to meet. There is no pressure to continue.</p></details><details><summary>How do I contact a mentor?</summary><p>Browse approved profiles and send a short introduction. Once accepted, a private conversation opens so you can agree on availability, format and any fees. Sessions are not booked or charged automatically.</p></details><details><summary>Who can see my progress?</summary><p>Only you. Community visibility is a separate choice. Your app progress is never added to your public community profile, and private journal text stays on your device.</p></details><details><summary>Why are there no groups near me yet?</summary><p>Treksor is growing. Only real, published groups and profiles appear here. You can start the first group around an activity you enjoy.</p></details></div></div></section>`}
function renderEcosystem(){return pageTop('THE TREKSOR ECOSYSTEM','Four dimensions.<br>One life, your way.','Find what you need today and take a next step with intention.')+`<section class="section ecosystem-intro"><div class="wrap">${pillarData.map((p,i)=>`<article class="ecosystem-row"><span class="number">0${i+1}</span><div><h2>${p.name}</h2><p>${p.text}</p></div><div class="practice"><h3>${p.practice}</h3><p>${p.description}</p>${btn('Try this first step ↗','practice',i,'ghost')}</div></article>`).join('')}<div class="quote-band"><p>Your growth is personal.<br>The journey can be shared.</p><a class="button" href="#/community">Explore Community ↗</a></div></div></section>`}
function authDialog(mode='login'){state.dialogContext={mode};const signup=mode==='signup';openDialog(signup?'Your next chapter starts here.':'Welcome back.',`<p class="lead">${signup?'Create your Treksor account.':'Use the same email and password as your Treksor app.'}</p><form id="auth-form" class="form-grid">${signup?'<label>Your name<input name="name" required minlength="2" maxlength="60" autocomplete="name"></label>':''}<label>Email<input name="email" type="email" required autocomplete="email" maxlength="254"></label><label>Password<input name="password" type="password" required minlength="${signup?8:1}" maxlength="128" autocomplete="${signup?'new-password':'current-password'}"></label>${signup?'<label class="checkbox"><input type="checkbox" required><span>I am 18 or older and agree to participate respectfully.</span></label>':''}<div class="form-error" role="alert"></div><button class="button" type="submit">${signup?'Create account':'Sign in'} ↗</button><p class="helper">${signup?'Check your email to confirm your account.':'If your app uses social sign-in, set up a password in the app first.'}</p></form><div class="auth-switch">${signup?'Already have an account?':'New to Treksor?'} ${btn(signup?'Sign in':'Create account',signup?'login':'signup','','ghost')}</div>`,'YOUR TREKSOR ACCOUNT')}
function principles(){openDialog('A space we care for together.',`<div class="dialog-text"><h3>Respect, without pressure</h3><p>An invitation is an option, never an obligation. Respect boundaries and the decision not to continue. Harassment, discrimination and unsolicited sexual content are not welcome.</p><h3>Meet thoughtfully</h3><p>Community is for adults aged 18 and over. Choose public places for first meetings, tell someone you trust and agree on the activity and its level in advance.</p><h3>Be honest</h3><p>Represent your identity and experience accurately. Mentors must explain the scope of their support. Verify people and terms before sending payments or personal documents.</p><h3>You stay in control</h3><p>Hide your profile, decline invitations, close conversations, block contacts or report concerns at any time.</p></div>`,'COMMUNITY GUIDELINES')}
function privacy(){openDialog('Your space. Clear boundaries.',`<div class="dialog-text"><h3>Your app profile and progress</h3><p>Your account name and photo are shared between the app and website. Progress snapshots are stored privately under your account, separately for each device. Only you can read them. Private journal text, mood-journal records and vision-board answers are not uploaded by progress sync.</p><h3>Community visibility</h3><p>Groups are public. One-to-one profiles are visible to signed-in members only when you opt in. Approved mentor profiles and profiles of your existing contacts are also visible to members. Your sign-in email is never displayed in Community.</p><h3>Conversations and reports</h3><p>Messages are visible to participants. Reports are visible to their sender and Treksor administrators. Sign out on shared devices.</p><h3>Your controls</h3><p>Edit or hide your community profile, leave groups, withdraw a mentor application and manage blocked contacts in My space. Closing a connection keeps its history. Complete account deletion is not currently available from this website.</p></div>`,'PRIVACY')}
